_cached = {}

def load_player_sprite(width=126):
    """Return the rear-view armed moose sprite as a Pygame Surface."""
    width = int(width)
    if width in _cached:
        return _cached[width]

    indexes = zlib.decompress(base64.b85decode(_DATA.encode("ascii")))
    source = pygame.Surface((_WIDTH, _HEIGHT), pygame.SRCALPHA)

    i = 0
    for y in range(_HEIGHT):
        for x in range(_WIDTH):
            source.set_at((x, y), _PALETTE[indexes[i]])
            i += 1

    height = round(_HEIGHT * width / _WIDTH)
    result = pygame.transform.smoothscale(source, (width, height))
    _cached[width] = result
    return result
